import csv
rows=list(csv.DictReader(open('dataset/hospital_compensation_registry.csv')))
by_id={r['patient_id']:r for r in rows}

def show(pid, tag=''):
    r=by_id.get(pid)
    if not r: 
        print(f'  {pid}: MISSING'); return
    print(f\"  {pid} {r['full_name']:<16} EC->{r['emergency_contact_patient_id']:<8} reason={r['compensation_reason'] or '(none)':<28} cov={r['coverage_status'] or '-':<8} date={r['record_date'] or '-'} \${r['direct_payment_usd'] or '-'}\")

for claim in ['PAT_265','PAT_033','PAT_006']:
    r=by_id[claim]
    print('='*90)
    print(f'CLAIM {claim} {r[\"full_name\"]} :: {r[\"compensation_reason\"]} date={r[\"record_date\"]}')
    print(' claimant:'); show(claim)
    ec=r['emergency_contact_patient_id']
    print(' its EC (named contact):'); show(ec)
    print(' people who list the claimant as their EC:')
    for x in rows:
        if x['emergency_contact_patient_id']==claim: show(x['patient_id'])
    print(' people who list the EC as their EC:')
    for x in rows:
        if x['emergency_contact_patient_id']==ec: show(x['patient_id'])
"

