python3 -c "
import csv
rows=list(csv.DictReader(open('dataset/hospital_compensation_registry.csv')))
by_id={r['patient_id']:r for r in rows}
has_claim=lambda r: bool(r['compensation_reason'])

claimants={'PAT_265':'Quill','PAT_033':'Rivera','PAT_006':'Jones'}
print('All patients grouped by the 3 claimant surnames, with claim status:')
for pid,sur in claimants.items():
    print(f'--- surname {sur} (claimant {pid} {by_id[pid][\"full_name\"]}) ---')
    for r in rows:
        if r['second_name']==sur:
            ec=r['emergency_contact_patient_id']
            # relationship to claimant?
            rel=[]
            if ec==pid: rel.append('names_claimant_as_EC')
            if by_id[pid]['emergency_contact_patient_id']==r['patient_id']: rel.append('claimant_names_them_as_EC')
            print(f\"   {r['patient_id']} {r['full_name']:<16} claim={'YES' if has_claim(r) else 'no ':<3} cov={r['coverage_status'] or '-':<8} EC->{ec:<8} {rel}\")
"

